const COLORS: Record<ObstacleDescriptor['type'], number> = {
  wall: 0x75808f,
  bumper: 0xe34f4f,
  pillar: 0x8c96a3,
  block: 0x788391,
  spinner: 0xf1c84a,
  windmill: 0x5fa9e8,
  gate: 0xe68a3f,
  platform: 0x69b977,
  water: 0x3b94d9,
  void: 0x272733,
  'reset-zone': 0xd95c9c,
};

class ThreeObstacleVisual implements ObstacleVisual {
  readonly object: THREE.Mesh;
  private disposed = false;

  constructor(descriptor: ObstacleDescriptor) {
    const size = descriptor.size;
    const geometry = new THREE.BoxGeometry(size.x, size.y, size.z);
    const material = new THREE.MeshStandardMaterial({
      color: COLORS[descriptor.type],
      transparent: descriptor.type === 'water' || descriptor.type === 'void' || descriptor.type === 'reset-zone',
      opacity: descriptor.type === 'water' ? 0.58 : descriptor.type === 'void' ? 0.32 : descriptor.type === 'reset-zone' ? 0.4 : 1,
    });
    this.object = new THREE.Mesh(geometry, material);
    this.object.name = `obstacle:${descriptor.id}`;
    this.object.castShadow = !('penaltyStrokes' in descriptor) && descriptor.type !== 'water';
    this.object.receiveShadow = true;
    const scale = descriptor.transform.scale;
    if (scale) this.object.scale.set(scale.x, scale.y, scale.z);
  }

  setPose(pose: ObstaclePose): void {
    if (this.disposed) return;
    this.object.position.set(pose.position.x, pose.position.y, pose.position.z);
    this.object.quaternion.set(pose.rotation.x, pose.rotation.y, pose.rotation.z, pose.rotation.w);
  }

  setEnabled(enabled: boolean): void {
    if (!this.disposed) this.object.visible = enabled;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.object.removeFromParent();
    this.object.geometry.dispose();
    const materials = Array.isArray(this.object.material) ? this.object.material : [this.object.material];
    for (const material of materials) material.dispose();
  }
}

export class ThreeObstacleVisualFactory implements ObstacleVisualFactory {
  constructor(private readonly parent: THREE.Object3D) {}

  create(descriptor: ObstacleDescriptor): ObstacleVisual {
    const visual = new ThreeObstacleVisual(descriptor);
    this.parent.add(visual.object);
    return visual;
  }
}
