import RAPIER from '@dimforge/rapier3d-compat';
import type { ObstacleDescriptor } from '../courses/types';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { ObstacleBody, ObstacleBodyFactory, ObstaclePose } from './types';

class RapierObstacleBody implements ObstacleBody {
  private disposed = false;

  constructor(
    private readonly world: RAPIER.World,
    readonly rigidBody: RAPIER.RigidBody,
    readonly collider: RAPIER.Collider,
    private readonly kinematic: boolean,
  ) {}

  setPose(pose: ObstaclePose): void {
    if (this.disposed) return;
    if (this.kinematic) {
      this.rigidBody.setNextKinematicTranslation(pose.position);
      this.rigidBody.setNextKinematicRotation(pose.rotation);
    } else {
      this.rigidBody.setTranslation(pose.position, false);
      this.rigidBody.setRotation(pose.rotation, false);
    }
  }

  setEnabled(enabled: boolean): void {
    if (!this.disposed) this.rigidBody.setEnabled(enabled);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.world.removeRigidBody(this.rigidBody);
  }
}

export class RapierObstacleBodyFactory implements ObstacleBodyFactory {
  constructor(private readonly world: RAPIER.World) {}

  create(descriptor: ObstacleDescriptor): ObstacleBody {
    const moving = 'motion' in descriptor;
    const hazard = descriptor.type === 'water' || descriptor.type === 'void' || descriptor.type === 'reset-zone';
    const transformScale = descriptor.transform.scale ?? { x: 1, y: 1, z: 1 };
    const halfX = Math.max(0.001, Math.abs(descriptor.size.x * transformScale.x) * 0.5);
    const halfY = Math.max(0.001, Math.abs(descriptor.size.y * transformScale.y) * 0.5);
    const halfZ = Math.max(0.001, Math.abs(descriptor.size.z * transformScale.z) * 0.5);

    const bodyDesc = moving ? RAPIER.RigidBodyDesc.kinematicPositionBased() : RAPIER.RigidBodyDesc.fixed();
    const body = this.world.createRigidBody(bodyDesc);
    const membership = hazard ? CollisionLayers.SENSOR : CollisionLayers.OBSTACLE;
    const colliderDesc = RAPIER.ColliderDesc.cuboid(halfX, halfY, halfZ)
      .setSensor(hazard)
      .setFriction(hazard ? 0 : 0.65)
      .setRestitution('restitution' in descriptor ? descriptor.restitution ?? 0.15 : 0.15)
      .setCollisionGroups(collisionGroups(membership, CollisionLayers.BALL));
    const collider = this.world.createCollider(colliderDesc, body);
    return new RapierObstacleBody(this.world, body, collider, moving);
  }
}
