import type { ObstacleDescriptor } from '../courses/types';
import { DynamicObstacle } from './DynamicObstacle';
import type { ObstacleBodyFactory, ObstacleVisualFactory } from './types';

export class ObstacleManager {
  private readonly obstacles = new Map<string, DynamicObstacle>();
  private disposed = false;

  constructor(
    private readonly visualFactory: ObstacleVisualFactory,
    private readonly bodyFactory: ObstacleBodyFactory,
  ) {}

  get size(): number {
    return this.obstacles.size;
  }

  get(id: string): DynamicObstacle | undefined {
    return this.obstacles.get(id);
  }

  create(descriptor: ObstacleDescriptor): DynamicObstacle {
    if (this.disposed) throw new Error('ObstacleManager is disposed');
    if (this.obstacles.has(descriptor.id)) throw new Error(`Duplicate obstacle id: ${descriptor.id}`);
    const obstacle = new DynamicObstacle(descriptor, this.visualFactory, this.bodyFactory);
    this.obstacles.set(descriptor.id, obstacle);
    return obstacle;
  }

  createMany(descriptors: readonly ObstacleDescriptor[]): readonly DynamicObstacle[] {
    return descriptors.map((descriptor) => this.create(descriptor));
  }

  remove(id: string): boolean {
    const obstacle = this.obstacles.get(id);
    if (!obstacle) return false;
    obstacle.dispose();
    this.obstacles.delete(id);
    return true;
  }

  update(deltaSeconds: number): void {
    if (this.disposed) return;
    for (const obstacle of this.obstacles.values()) obstacle.update(deltaSeconds);
  }

  clear(): void {
    for (const obstacle of this.obstacles.values()) obstacle.dispose();
    this.obstacles.clear();
  }

  dispose(): void {
    if (this.disposed) return;
    this.clear();
    this.disposed = true;
  }
}
