    axis: { x: 1, y: 0, z: 0 },
    speed: Math.PI / 2,
    distance: 4,
  },
};

describe('DynamicObstacle lifecycle', () => {
  it('creates visual/body binding and applies the initial pose', () => {
    const visuals = new FakeVisualFactory();
    const bodies = new FakeBodyFactory();
    const obstacle = new DynamicObstacle(staticObstacle, visuals, bodies);

    expect(visuals.created).toHaveLength(1);
    expect(bodies.created).toHaveLength(1);
    expect(visuals.created[0].poses[0].position).toEqual({ x: 1, y: 2, z: 3 });
    expect(bodies.created[0].poses[0]).toEqual(visuals.created[0].poses[0]);
    obstacle.dispose();
