  it('updates translated motion deterministically and keeps visual/body synchronized', () => {
    const visuals = new FakeVisualFactory();
    const bodies = new FakeBodyFactory();
    const obstacle = new DynamicObstacle(movingObstacle, visuals, bodies);

    obstacle.update(1);
    const visualPose = visuals.created[0].poses.at(-1)!;
    const bodyPose = bodies.created[0].poses.at(-1)!;
    expect(visualPose.position.x).toBeCloseTo(6, 6);
    expect(visualPose.position.y).toBeCloseTo(0, 6);
    expect(visualPose.position.z).toBeCloseTo(-1, 6);
    expect(bodyPose).toEqual(visualPose);
  });

  it('propagates enabled state and disposal exactly once', () => {
    const visuals = new FakeVisualFactory();
    const bodies = new FakeBodyFactory();
    const obstacle = new DynamicObstacle({ ...staticObstacle, enabled: false }, visuals, bodies);

    expect(visuals.created[0].enabled).toBe(false);
    expect(bodies.created[0].enabled).toBe(false);
    obstacle.setEnabled(true);
    expect(visuals.created[0].enabled).toBe(true);
    expect(bodies.created[0].enabled).toBe(true);
    obstacle.dispose();
    obstacle.dispose();
    expect(visuals.created[0].disposeCount).toBe(1);
    expect(bodies.created[0].disposeCount).toBe(1);
